LANGUAGES = {
    "zh-Hant": "繁體中文", "zh-Hans": "简体中文",
    "en": "English", "ja": "日本語", "ko": "한국어",
}
TRANSLATION_PATTERNS = {
    language: re.compile("|".join(map(re.escape, sorted(messages, key=len, reverse=True))))
    for language, messages in UI_TRANSLATIONS.items() if messages
}


def requested_language(headers):
    for cookie in headers.get("Cookie", "").split(";"):
        name, _, value = cookie.strip().partition("=")
        if name == "server_files_language" and value in LANGUAGES:
            return value
    for item in headers.get("Accept-Language", "").lower().split(","):
        locale = item.split(";", 1)[0].strip()
        if locale == "zh" or locale.startswith(("zh-hant", "zh-tw", "zh-hk", "zh-mo")):
            return "zh-Hant"
        if locale.startswith("zh-"):
            return "zh-Hans"
        primary = locale.split("-", 1)[0]
        if primary in ("en", "ja", "ko"):
            return primary
    return "zh-Hant"


def localized(text, language):
    return UI_TRANSLATIONS.get(language, {}).get(text, text)


def localized_template(template, language, *, javascript=False):
    pattern = TRANSLATION_PATTERNS.get(language)
    if pattern is None:
        return template
    messages = UI_TRANSLATIONS[language]
    js_escapes = {ord(char): f"\\u{ord(char):04x}" for char in "\\'\x22\x60<>&"}
    return pattern.sub(lambda match: messages[match[0]].translate(js_escapes) if javascript
                       else escape(messages[match[0]], quote=True), template)


