def display_icon(name, extra=""):
    return (
        f'<svg aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none" '
        f'stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"{extra}>'
        f'<use href="#view-{name}"></use></svg>'
    )


def display_picker(name, label, choices, default, extra=""):
    if name == "view":
        trigger = "".join(display_icon(key, f' class="picker-glyph" data-glyph="{key}"') for key, _ in choices)
        trigger += display_icon("caret", ' class="picker-caret"')
    else:
        trigger = display_icon("theme")
    options = "".join(
        f'<button type="button" data-display-choice="{key}" aria-pressed="{str(key == default).lower()}">'
        f'{display_icon(key)}<span>{caption}</span></button>' for key, caption in choices
    )
    return (
        f'<details class="display-picker {name}-picker" data-display-picker="{name}">'
        f'<summary aria-label="{label}" title="{label}">{trigger}</summary>'
        f'<div class="display-options">{options}{extra}</div></details>'
    )


VIEW_PICKER = display_picker("view", "切換檔案檢視", (("icons", "圖像"), ("list", "列表"), ("columns", "直欄")), "list")


def settings_picker(language, recent_files=False):
    languages = "".join(
        f'<button type="button" data-language="{key}" lang="{key}" aria-pressed="{str(key == language).lower()}">'
        f'{escape(label)}</button>' for key, label in LANGUAGES.items()
    )
    menu = (
        '<details class="language-options"><summary>Language'
        + display_icon("caret", ' class="picker-caret"')
        + '</summary>' + languages + '</details>'
    )
    recent_toggle = (
        '<label class="recent-toggle"><input type="checkbox" data-recent-toggle>'
        '<span>顯示最近開啟的檔案</span></label>'
    ) if recent_files else ""
    return localized_template(display_picker(
        "theme", "設定", (("light", "白色背景"), ("dark", "深色背景")), "dark", recent_toggle + menu
    ), language)

