FILE_COVER_SCRIPT = """
(() => {
  const results = document.getElementById("preview-results");
  if (!("IntersectionObserver" in window)) return;
  const root = document.documentElement;
  const observed = new Set();
  const waiting = new Set();
  const active = new Map();
  const finished = new WeakSet();
  const enabled = () => root.dataset.fileView === "icons";

  async function makeRasterCover(response) {
    const url = URL.createObjectURL(await response.blob());
    try {
      const source = new Image();
      source.src = url;
      await source.decode();
      const scale = Math.min(1, 320 / source.naturalWidth, 180 / source.naturalHeight);
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(source.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(source.naturalHeight * scale));
      const context = canvas.getContext("2d");
      if (!context) throw new Error("No canvas context");
      context.drawImage(source, 0, 0, canvas.width, canvas.height);
      const cover = document.createElement("img");
      cover.alt = "";
      cover.draggable = false;
      cover.src = canvas.toDataURL("image/webp", 0.84);
      return cover;
    } finally {
      URL.revokeObjectURL(url);
    }
  }

  async function load(tile, controller) {
    try {
      const response = await fetch(tile.dataset.coverUrl, { signal: controller.signal, redirect: "error" });
      if (!response.ok) throw new Error("Cover unavailable");
      const type = response.headers.get("Content-Type")?.split(";")[0];
      let cover;
      if (tile.dataset.coverKind === "image" && ["image/png", "image/jpeg", "image/webp"].includes(type)) {
        cover = await makeRasterCover(response);
      } else if (tile.dataset.coverKind === "text" && type === "text/plain") {
        cover = document.createElement("pre");
        cover.textContent = await response.text();
      } else {
        throw new Error("Invalid cover type");
      }
      if (!controller.signal.aborted && enabled() && tile.isConnected) {
        cover.className = "cover-content";
        cover.setAttribute("aria-hidden", "true");
        tile.append(cover);
      }
    } catch {
      // Keep the file type icon when a preview cannot be decoded.
    } finally {
      active.delete(tile);
      if (!controller.signal.aborted) finished.add(tile);
      else if (enabled() && tile.isConnected) {
        observed.add(tile);
        observer.observe(tile);
      }
      pump();
    }
  }

  function pump() {
    if (!enabled()) return;
    for (const tile of waiting) {
      if (active.size >= 2) break;
      waiting.delete(tile);
      observed.delete(tile);
      observer.unobserve(tile);
      if (!tile.isConnected) continue;
      const controller = new AbortController();
      active.set(tile, controller);
      load(tile, controller);
    }
  }

  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting && observed.has(entry.target)) waiting.add(entry.target);
      else waiting.delete(entry.target);
    }
    pump();
  });

  function rescan() {
    const display = enabled();
    for (const tile of observed) {
      if (display && tile.isConnected) continue;
      observer.unobserve(tile);
      observed.delete(tile);
      waiting.delete(tile);
    }
    for (const [tile, controller] of active) {
      if (!display || !tile.isConnected) controller.abort();
    }
    if (!display) return;
    for (const tile of results.querySelectorAll("[data-cover-url]")) {
      if (finished.has(tile) || observed.has(tile) || active.has(tile) || tile.querySelector(".cover-content")) continue;
      observed.add(tile);
      observer.observe(tile);
    }
    pump();
  }

  new MutationObserver(rescan).observe(results, { childList: true });
  new MutationObserver(rescan).observe(root, { attributes: true, attributeFilter: ["data-file-view"] });
  rescan();
})();
"""

DOWNLOAD_SCRIPT = r"""
(() => {
  const largeDownload = 100 * 1024 * 1024;
  const panel = document.getElementById("download-progress");
  const status = document.getElementById("download-status");
  const meter = panel.querySelector("progress");
  const stop = document.getElementById("download-stop");
  const dialog = document.getElementById("download-choice");
  const details = document.getElementById("download-details");
  const direct = document.getElementById("download-direct");
  const directoryPicker = typeof window.showDirectoryPicker === "function";
  const savePicker = typeof window.showSaveFilePicker === "function";
  const number = new Intl.NumberFormat(document.documentElement?.lang || undefined, { maximumFractionDigits: 1 });
  let active = null;

  function sizeLabel(bytes) {
    if (bytes < 1024) return number.format(bytes) + " B";
    if (bytes < 1024 ** 2) return number.format(bytes / 1024) + " KiB";
    if (bytes < 1024 ** 3) return number.format(bytes / 1024 ** 2) + " MiB";
    return number.format(bytes / 1024 ** 3) + " GiB";
  }

  function progress(message, loaded, total) {
    panel.hidden = false;
    meter.hidden = false;
    status.textContent = message;
    if (total > 0) {
      meter.max = total;
      meter.value = loaded;
    } else {
      meter.removeAttribute("value");
    }
  }

  function endpoint(path, mode) {
    const url = new URL(path, location.href);
    url.search = "?" + mode + "=1";
    return url.href;
  }

  async function get(url, signal) {
    const response = await fetch(url, { signal });
    if (!response.ok) {
      if (response.status === 404) throw new Error("檔案或資料夾已移動或不存在。");
      if (response.status === 507) throw new Error("伺服器沒有足夠空間建立 ZIP。");
      throw new Error("伺服器無法讀取這個下載項目（" + response.status + "）。");
    }
    return response;
  }

  function nativeDownload(url, name) {
    const link = document.createElement("a");
    link.href = url;
    link.download = name;
    document.body.append(link);
    link.click();
    link.remove();
  }

  function components(path) {
    const parts = path.split("/");
    if (parts.some((name) => !name || name === "." || name === ".." || name.includes("\\"))) {
      throw new Error("資料夾包含本機無法直接儲存的名稱，請改用 ZIP。");
    }
    return parts;
  }

  function checkLocalPaths(plan) {
    const names = new Set();
    try {
      for (const path of [plan.name, ...plan.directories, ...plan.files.map((file) => file.path)]) {
        components(path);
      }
      for (const path of [...plan.directories, ...plan.files.map((file) => file.path)]) {
        const normalized = path.normalize("NFC").toLowerCase();
        if (names.has(normalized)) return false;
        names.add(normalized);
      }
      return true;
    } catch {
      return false;
    }
  }

  async function newFolder(parent, name) {
    const used = new Set();
    for await (const existing of parent.keys()) used.add(existing.normalize("NFC").toLowerCase());
    let candidate = name;
    let suffix = 2;
    while (used.has(candidate.normalize("NFC").toLowerCase())) candidate = name + " (" + suffix++ + ")";
    return parent.getDirectoryHandle(candidate, { create: true });
  }

  async function subfolder(root, parts) {
    for (const name of parts) root = await root.getDirectoryHandle(name, { create: true });
    return root;
  }

  async function receive(response, signal, onChunk) {
    const reader = response.body?.getReader();
    if (!reader) throw new Error("瀏覽器無法讀取下載串流。");
    try {
      while (true) {
        signal.throwIfAborted();
        const chunk = await reader.read();
        if (chunk.done) break;
        await onChunk(chunk.value);
      }
    } finally {
      await reader.cancel().catch(() => {});
      reader.releaseLock();
    }
  }

  async function saveResponse(response, handle, signal, onProgress, bufferLimit = Infinity) {
    const total = Number(response.headers.get("Content-Length"));
    const chunks = [];
    const writer = handle ? await handle.createWritable() : null;
    let loaded = 0;
    try {
      await receive(response, signal, async (chunk) => {
        loaded += chunk.byteLength;
        if (writer) await writer.write(chunk);
        else {
          if (loaded > bufferLimit) throw new RangeError("buffer limit");
          chunks.push(chunk);
        }
        onProgress(loaded, total);
      });
      signal.throwIfAborted();
      if (writer) await writer.close();
    } catch (error) {
      if (writer) await writer.abort().catch(() => {});
      throw error;
    }
    return writer ? null : new Blob(chunks, { type: "application/octet-stream" });
  }

  async function saveFolder(plan, parent, signal) {
    const root = await newFolder(parent, plan.name);
    let completed = 0;
    try {
      for (const directory of plan.directories) {
        signal.throwIfAborted();
        await subfolder(root, components(directory));
      }
      for (const file of plan.files) {
        const parts = components(file.path);
        const name = parts.pop();
        const response = await get(file.url, signal);
        if (Number(response.headers.get("Content-Length")) !== file.size) {
          await response.body?.cancel();
          throw new Error("伺服器上的檔案大小已變更，請重新下載。");
        }
        const folder = await subfolder(root, parts);
        const handle = await folder.getFileHandle(name, { create: true });
        await saveResponse(response, handle, signal, (bytes) => {
          progress("下載 " + root.name + " · " + sizeLabel(completed + bytes) + " / " + sizeLabel(plan.size),
            completed + bytes, plan.size);
        });
        completed += file.size;
      }
    } catch (error) {
      if (signal.aborted) throw error;
      throw new Error("本機資料夾 " + root.name + " 可能只收到部分內容。" + error.message);
    }
    return root.name;
  }

  function choose(plan, large) {
    const canSaveFolder = directoryPicker && checkLocalPaths(plan);
    direct.hidden = plan.directory && !canSaveFolder;
    direct.textContent = plan.directory ? "選擇儲存位置" : "直接下載";
    details.textContent = plan.name + " · " + sizeLabel(plan.size)
      + (large ? "。項目達 100 MiB，可選擇打包成 ZIP。" : "。")
      + (plan.directory && !canSaveFolder ? " 這個資料夾可以用 ZIP 下載。" : "");
    return new Promise((resolve, reject) => {
      const form = dialog.querySelector("form");
      function submit(event) {
        event.preventDefault();
        const mode = event.submitter?.value || "cancel";
        if (mode === "cancel") {
          dialog.close();
          return;
        }
        const archive = mode === "zip";
        const name = archive ? plan.name + ".zip" : plan.name;
        try {
          let picker;
          if (!archive && plan.directory) picker = window.showDirectoryPicker({ mode: "readwrite" });
          else if (savePicker) picker = window.showSaveFilePicker({ suggestedName: name });
          resolve(Promise.resolve(picker).then((handle) => ({ archive, name, handle })));
        } catch (error) {
          reject(error);
        } finally {
          dialog.close();
        }
      }
      dialog.addEventListener("close", () => {
        form.removeEventListener("submit", submit);
        reject(new DOMException("Cancelled", "AbortError"));
      }, { once: true });
      form.addEventListener("submit", submit);
      dialog.showModal();
    });
  }

  async function download(path) {
    resetSuccessStatus(panel);
    const controller = new AbortController();
    active = controller;
    const signal = controller.signal;
    stop.textContent = "取消";
    progress("正在計算下載大小…");
    let copyingFolder = false;
    try {
      const plan = await (await get(endpoint(path, "transfer"), signal)).json();
      const large = plan.size >= largeDownload;
      const selection = plan.directory || large ? await choose(plan, large) : { archive: false, name: plan.name };
      const { archive, name, handle } = selection;
      signal.throwIfAborted();
      if (plan.directory && !archive) {
        copyingFolder = true;
        progress("正在建立本機資料夾…");
        const folderName = await saveFolder(plan, handle, signal);
        progress("已下載資料夾 " + folderName, 1, 1);
        scheduleSuccessStatus(panel);
        return;
      }
      const url = endpoint(path, archive ? "archive" : "download");
      if (!handle && large) {
        nativeDownload(url, name);
        status.textContent = "已交給瀏覽器下載。請在瀏覽器的下載清單查看進度。";
        meter.hidden = true;
        return;
      }
      progress(archive ? "伺服器正在建立 ZIP…" : "下載 " + name + "…");
      const response = await get(url, signal);
      const file = await saveResponse(response, handle, signal, (loaded, total) => {
        progress("下載 " + name + " · " + sizeLabel(loaded) + (total ? " / " + sizeLabel(total) : ""), loaded, total);
      }, largeDownload + 16 * 1024 * 1024);
      if (file) {
        const blobUrl = URL.createObjectURL(file);
        nativeDownload(blobUrl, name);
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
      }
      progress("已下載 " + name, 1, 1);
      scheduleSuccessStatus(panel);
    } catch (error) {
      if (error instanceof RangeError) {
        status.textContent = "下載超過網頁的暫存容量，請重新下載並選擇儲存位置。";
      } else if (error.name === "AbortError") {
        status.textContent = copyingFolder ? "已取消下載，本機可能有部分檔案。" : "已取消下載。";
      } else {
        status.textContent = "下載失敗。" + error.message;
      }
      meter.hidden = true;
    } finally {
      active = null;
      stop.textContent = "關閉";
    }
  }

  stop.addEventListener("click", () => {
    if (active) active.abort();
    else {
      resetSuccessStatus(panel);
      panel.hidden = true;
    }
  });
  document.addEventListener("click", (event) => {
    const link = event.target.closest("a[data-transfer-url]");
    if (!link || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    if (active) return;
    if (link.id === "preview-download") document.getElementById("file-preview").close();
    download(link.dataset.transferUrl);
  });
})();
"""

