UPLOAD_SCRIPT = """
(() => {
  const results = document.getElementById("preview-results");
  const uploadArea = document.getElementById("file-browser") || results;
  const config = document.getElementById("upload-token").dataset;
  const progressBox = document.getElementById("upload-progress");
  const progress = progressBox.querySelector("progress");
  const status = document.getElementById("upload-status");
  const bytes = document.getElementById("upload-bytes");
  const failures = document.getElementById("upload-failures");
  const conflict = document.getElementById("upload-conflict");
  const locale = document.documentElement.lang || undefined;
  const byteNumber = new Intl.NumberFormat(locale);
  const percentNumber = new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 });
  let uploading = false;
  let highlightedTarget;

  function showBytes(uploaded, total, done = false) {
    const sent = Math.min(total, Math.max(0, uploaded));
    const percent = total ? (100 * sent) / total : done ? 100 : 0;
    progress.value = percent;
    bytes.textContent = byteNumber.format(sent) + " B / " + byteNumber.format(total) + " B · " +
      percentNumber.format(Math.floor(percent) / 100);
    bytes.hidden = false;
  }

  function highlight(target) {
    highlightedTarget?.classList.remove("drag-over");
    highlightedTarget = target;
    target?.classList.add("drag-over");
  }

  function resolveConflict(name) {
    document.getElementById("upload-conflict-name").textContent = name;
    conflict.returnValue = "skip";
    return new Promise((resolve) => {
      conflict.addEventListener("close", () => resolve(conflict.returnValue === "copy"), { once: true });
      conflict.showModal();
    });
  }

  function postUpload(target, file, path, asCopy, onProgress) {
    return new Promise((resolve, reject) => {
      const request = new XMLHttpRequest();
      const destination = new URL(target);
      let active = true;
      if (!file) destination.searchParams.set("mkdir", "1");
      if (file) {
        request.upload.onprogress = (event) => {
          if (active) onProgress(Math.min(file.size, event.loaded), false);
        };
        request.upload.onload = () => { if (active) onProgress(file.size, true); };
      }
      request.open("POST", destination);
      request.setRequestHeader("X-Preview-Token", config.token);
      if (file) {
        request.setRequestHeader("Content-Type", "application/octet-stream");
        request.setRequestHeader("X-Upload-Name", encodeURIComponent(path.at(-1)));
        if (asCopy) request.setRequestHeader("X-Upload-Conflict", "copy");
      } else {
        request.setRequestHeader("X-Upload-Path", encodeURIComponent(path.join("/")));
      }
      request.onload = () => {
        active = false;
        if (file && request.status === 409 && !asCopy) { resolve(null); return; }
        let result;
        try { result = JSON.parse(request.responseText) || {}; } catch { result = {}; }
        if ((request.status !== 201 && (file || request.status !== 200))
            || (file && typeof result.name !== "string")) {
          reject(new Error(result.error || (file ? "上傳未完成" : "無法建立資料夾")));
          return;
        }
        resolve(result);
      };
      request.onerror = request.onabort = () => {
        active = false;
        reject(new Error("連線中斷，請再試一次"));
      };
      request.send(file || null);
    });
  }

  function newSelection() {
    return { folders: new Map(), files: [], errors: [] };
  }

  function addFolder(selection, path) {
    for (let index = 1; index <= path.length; index += 1) {
      const parent = path.slice(0, index);
      selection.folders.set(parent.join("/"), parent);
    }
  }

  function addFile(selection, file, path) {
    addFolder(selection, path.slice(0, -1));
    selection.files.push({ file, path });
  }

  function selectedFiles(files) {
    const selection = newSelection();
    for (const file of files) addFile(selection, file, (file.webkitRelativePath || file.name).split("/"));
    return selection;
  }

  async function addDroppedEntry(selection, entry, parent) {
    const path = [...parent, entry.name];
    try {
      if (entry.isFile) {
        const file = await new Promise((resolve, reject) => entry.file(resolve, reject));
        addFile(selection, file, path);
      } else if (entry.isDirectory) {
        addFolder(selection, path);
        const reader = entry.createReader();
        // Some browsers limit each readEntries call to 100 items.
        for (;;) {
          const children = await new Promise((resolve, reject) => reader.readEntries(resolve, reject));
          if (!children.length) break;
          for (const child of children) await addDroppedEntry(selection, child, path);
        }
      }
    } catch {
      selection.errors.push(path.join("/") + "：無法讀取");
    }
  }

  async function droppedFiles(items) {
    const selection = newSelection();
    for (const { entry, file } of items) {
      if (entry) await addDroppedEntry(selection, entry, []);
      else if (file) addFile(selection, file, [file.name]);
    }
    return selection;
  }

  function destinationUrl(base, path, directory = false) {
    return path.length ? new URL(path.map(encodeURIComponent).join("/") + (directory ? "/" : ""), base) : base;
  }

  async function uploadSelection(getSelection, target) {
    if (uploading) return;
    uploading = true;
    resetSuccessStatus(progressBox);
    progressBox.hidden = false;
    progress.removeAttribute("value");
    bytes.hidden = true;
    failures.textContent = "";
    status.textContent = "正在讀取選取的檔案和資料夾…";
    try {
      await uploadEntries(await getSelection(), target);
    } catch (failure) {
      progress.value = 0;
      bytes.hidden = true;
      status.textContent = "無法處理上傳項目";
      failures.textContent = failure.message;
    } finally {
      uploading = false;
    }
  }

  async function uploadEntries(selection, target) {
    const base = new URL(target, window.location.href);
    const folderName = config.root + decodeURIComponent(base.pathname);
    const directories = Array.from(selection.folders.values()).sort((a, b) => a.length - b.length);
    const files = selection.files;
    const errors = selection.errors;
    const copies = [];
    const blocked = new Set();
    let succeeded = 0;
    let created = 0;
    let skipped = 0;
    let committed = 0;
    const total = files.reduce((amount, item) => amount + item.file.size, 0);
    showBytes(0, total);

    for (const [index, path] of directories.entries()) {
      const name = path.join("/");
      status.textContent = "準備資料夾 " + (index + 1) + "/" + directories.length + " · " + name;
      if (blocked.has(path.slice(0, -1).join("/"))) {
        blocked.add(name);
      } else {
        try {
          const result = await postUpload(base, null, path);
          if (result.created) created += 1;
        } catch (failure) {
          blocked.add(name);
          errors.push(name + "：" + failure.message);
        }
      }
    }

    for (const [index, { file, path }] of files.entries()) {
      const name = path.join("/");
      const parent = path.slice(0, -1);
      const folderUrl = destinationUrl(base, parent, true);
      const sending = "上傳 " + (index + 1) + "/" + files.length + " · " + name + " → " + folderName;
      const finalizing = "正在等待伺服器寫入檔案…" + " · " + name;
      status.textContent = sending;
      const sendFile = (asCopy) => {
        status.textContent = file.size ? sending : finalizing;
        return postUpload(folderUrl, file, path, asCopy, (loaded, sent) => {
          showBytes(committed + loaded, total);
          if (sent) status.textContent = finalizing;
        });
      };
      try {
        if (blocked.has(parent.join("/"))) throw new Error("目標資料夾無法建立");
        const existing = await fetch(destinationUrl(base, path), { method: "HEAD" });
        const asCopy = existing.ok;
        if (asCopy && !(await resolveConflict(name))) { skipped += 1; continue; }
        let result = await sendFile(asCopy);
        if (!result) {
          showBytes(committed, total);
          if (!(await resolveConflict(name))) { skipped += 1; continue; }
          result = await sendFile(true);
        }
        if (result.name !== path.at(-1)) copies.push([...parent, result.name].join("/"));
        succeeded += 1;
        committed += file.size;
      } catch (failure) {
        errors.push(name + "：" + failure.message);
      } finally {
        showBytes(committed, total);
      }
    }
    status.textContent = "已上傳 " + succeeded + " 個檔案" +
      (created ? " · 建立 " + created + " 個資料夾" : "") +
      (skipped ? " · 略過 " + skipped + " 個" : "") +
      (errors.length ? " · 失敗 " + errors.length + " 個" : "");
    if (!directories.length && !files.length && !errors.length) status.textContent = "沒有可上傳的項目";
    const details = errors.slice(0, 15);
    if (errors.length > details.length) details.push("還有 " + (errors.length - details.length) + " 項失敗");
    if (copies.length) details.push("副本：" + copies.slice(0, 10).join("、") + (copies.length > 10 ? " 等" : ""));
    failures.textContent = details.join("　");
    showBytes(committed, total, !errors.length && !skipped && (files.length > 0 || directories.length > 0));
    if (succeeded || created) {
      document.dispatchEvent(new Event("preview-upload-complete"));
      if (!errors.length && !skipped) scheduleSuccessStatus(progressBox);
    }
  }

  function hasDraggedFiles(event) {
    return event.dataTransfer && (Array.from(event.dataTransfer.types).includes("Files") || event.dataTransfer.files.length);
  }

  uploadArea.addEventListener("dragover", (event) => {
    const target = event.target.closest("[data-upload-target]");
    if (!target || uploading || !hasDraggedFiles(event)) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    if (target !== highlightedTarget) highlight(target);
  });
  uploadArea.addEventListener("dragleave", (event) => {
    if (highlightedTarget && !highlightedTarget.contains(event.relatedTarget)) highlight(null);
  });
  uploadArea.addEventListener("drop", (event) => {
    if (!hasDraggedFiles(event)) return;
    event.preventDefault();
    const target = event.target.closest("[data-upload-target]");
    highlight(null);
    if (!target || uploading) return;
    // The browser grants access to DataTransfer items only during the drop event.
    const items = Array.from(event.dataTransfer.items || []).filter((item) => item.kind === "file");
    const dropped = items.map((item) => {
      const getEntry = item.getAsEntry || item.webkitGetAsEntry;
      const entry = getEntry?.call(item);
      return { entry, file: entry ? null : item.getAsFile() };
    });
    const fallback = Array.from(event.dataTransfer.files);
    uploadSelection(() => dropped.some((item) => item.entry || item.file) ? droppedFiles(dropped) : selectedFiles(fallback),
                    target.dataset.uploadTarget);
  });
  results.addEventListener("click", (event) => {
    if (uploading) return;
    const button = event.target.closest("[data-upload-picker], [data-folder-picker]");
    if (!button) return;
    const selector = button.matches("[data-folder-picker]") ? "[data-folder-input]" : "[data-upload-input]";
    button.closest(".upload-panel").querySelector(selector).click();
  });
  results.addEventListener("change", (event) => {
    if (!event.target.matches("[data-upload-input], [data-folder-input]")) return;
    const files = Array.from(event.target.files);
    const target = event.target.closest("[data-upload-target]");
    event.target.value = "";
    if (target && files.length) uploadSelection(() => selectedFiles(files), target.dataset.uploadTarget);
  });
  document.addEventListener("dragover", (event) => {
    if (!hasDraggedFiles(event)) return;
    if (!event.defaultPrevented) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "none";
    }
  });
  document.addEventListener("drop", (event) => {
    if (hasDraggedFiles(event)) event.preventDefault();
  });
})();
"""

