FILE_TAG_SCRIPT = """
(() => {
  const results = document.getElementById("preview-results");
  const token = document.getElementById("upload-token").dataset.token;
  const popover = document.getElementById("file-tag-popover");
  const filename = document.getElementById("file-tag-filename");
  const error = document.getElementById("file-tag-error");
  const status = document.getElementById("preview-status");
  const options = Array.from(popover.querySelectorAll("button[data-tag-color]"));
  const labels = new Map(options.map((option) => [option.dataset.tagColor, option.dataset.tagLabel]));
  let anchor = null;
  let pending = false;
  let refreshNeeded = false;

  function refresh() {
    if (!refreshNeeded) return;
    refreshNeeded = false;
    document.dispatchEvent(new Event("preview-upload-complete"));
  }

  function close(restoreFocus = false) {
    if (!anchor) return;
    const previous = anchor;
    anchor = null;
    previous.setAttribute("aria-expanded", "false");
    popover.hidden = true;
    if (restoreFocus && previous.isConnected) previous.focus({ preventScroll: true });
    refresh();
  }

  function place() {
    if (!anchor || popover.hidden) return;
    const target = anchor.getBoundingClientRect();
    if (target.bottom < 0 || target.top > window.innerHeight) { close(); return; }
    const width = popover.offsetWidth;
    const height = popover.offsetHeight;
    const margin = 8;
    const left = Math.max(margin, Math.min(target.right - width, window.innerWidth - width - margin));
    const top = target.bottom + height + margin <= window.innerHeight
      ? target.bottom + 5
      : Math.max(margin, target.top - height - 5);
    popover.style.left = left + "px";
    popover.style.top = top + "px";
  }

  function showChoices(tags) {
    for (const option of options) {
      option.setAttribute("aria-pressed", String(tags.includes(option.dataset.tagColor)));
    }
  }

  function renderTags(button, tags) {
    button.dataset.tagColors = tags.join(" ");
    const list = button.closest(".entry")?.querySelector(".file-tag-list");
    if (!list) return;
    list.replaceChildren(...tags.map((color) => {
      const dot = document.createElement("span");
      dot.className = "tag-dot";
      dot.dataset.tagColor = color;
      dot.setAttribute("aria-hidden", "true");
      return dot;
    }));
    const label = tags.length ? "標籤：" + tags.map((color) => labels.get(color)).join("、") : "";
    list.setAttribute("aria-label", label);
    list.title = label;
    list.hidden = !tags.length;
  }

  results.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-tag-url]");
    if (!button || pending) return;
    if (anchor === button) { close(true); return; }
    anchor?.setAttribute("aria-expanded", "false");
    anchor = button;
    button.setAttribute("aria-expanded", "true");
    filename.textContent = button.dataset.tagName;
    filename.title = button.dataset.tagName;
    error.hidden = true;
    showChoices(button.dataset.tagColors.split(" "));
    popover.hidden = false;
    place();
    options[0].focus({ preventScroll: true });
  });

  popover.addEventListener("click", async (event) => {
    const choice = event.target.closest("button[data-tag-color]");
    const button = anchor;
    if (!choice || !button || pending) return;
    pending = true;
    error.hidden = true;
    popover.setAttribute("aria-busy", "true");
    for (const option of options) option.disabled = true;
    try {
      const url = new URL(button.dataset.tagUrl, window.location.origin);
      url.searchParams.set("tag", "1");
      const response = await fetch(url, {
        method: "POST",
        body: "",
        redirect: "error",
        headers: {
          "X-Preview-Token": token,
          "X-Preview-File-Mtime": button.dataset.tagMtime,
          "X-Preview-Tag": choice.dataset.tagColor,
          "X-Preview-Tag-Enabled": choice.getAttribute("aria-pressed") === "true" ? "0" : "1",
        },
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !Array.isArray(data.tags)) {
        if (response.status === 409) refreshNeeded = true;
        throw new Error(data.error || "無法更新標籤");
      }
      const tags = Array.from(labels.keys()).filter((color) => data.tags.includes(color));
      for (const candidate of results.querySelectorAll("button[data-tag-url]")) {
        if (candidate.dataset.tagUrl === button.dataset.tagUrl && candidate.dataset.tagMtime === button.dataset.tagMtime) {
          renderTags(candidate, tags);
        }
      }
      refreshNeeded = true;
      status.textContent = "已更新 " + button.dataset.tagName + " 的標籤";
      if (anchor === button) showChoices(tags);
    } catch (failure) {
      if (anchor === button) {
        error.textContent = failure.message || "無法更新標籤";
        error.hidden = false;
      } else {
        status.textContent = failure.message || "無法更新標籤";
      }
    } finally {
      pending = false;
      popover.removeAttribute("aria-busy");
      for (const option of options) option.disabled = false;
      if (anchor === button) {
        place();
        if (anchor === button) choice.focus({ preventScroll: true });
      } else {
        refresh();
      }
    }
  });

  document.addEventListener("pointerdown", (event) => {
    if (!anchor || popover.contains(event.target) || event.target.closest("button[data-tag-url]")) return;
    close();
  });
  document.addEventListener("focusin", (event) => {
    if (!anchor || pending || popover.contains(event.target) || event.target.closest("button[data-tag-url]")) return;
    close();
  });
  document.addEventListener("keydown", (event) => {
    if (!anchor || event.key !== "Escape") return;
    event.preventDefault();
    close(true);
  });
  window.addEventListener("resize", place);
  window.addEventListener("scroll", place, { capture: true, passive: true });
  new MutationObserver(() => { if (anchor && !anchor.isConnected) close(); }).observe(results, { childList: true });
})();
"""

